// Мова для Intl: та, якою показано сайт; без ініціалізованого i18n
// (історії, тести) — англійська.
export const uiLanguage = (i18n) => (i18n.resolvedLanguage ?? i18n.language ?? 'en');
// Ініціали для аватара: з імені й прізвища, якщо обидва є, інакше дві
// перші літери нікнейму.
export const userInitials = (user) => {
    const first = user.user_firstname?.trim();
    const last = user.user_lastname?.trim();
    const source = first && last
        ? `${first[0]}${last[0]}`
        : Array.from(user.user_nickname.trim()).slice(0, 2).join('');
    return source.toUpperCase() || '?';
};
// «12 березня 2025» мовою сайту, у часовому поясі браузера.
export const formatMemberSince = (ts, language) => (new Date(ts).toLocaleDateString(language, {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
}));
// ISO-код країни → назва мовою сайту; невідомий код — як є.
export const countryName = (code, language) => {
    try {
        return new Intl.DisplayNames([language], { type: 'region' }).of(code) ?? code;
    }
    catch {
        return code;
    }
};
const MINUTE_MS = 60000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
// Остання активність сесії: «щойно» до хвилини, далі «N хв / год / дн тому».
export const formatLastActive = (ts, now, language) => {
    const ago = Math.max(0, now - ts);
    if (ago < MINUTE_MS)
        return null;
    const rtf = new Intl.RelativeTimeFormat(language, { numeric: 'always', style: 'short' });
    if (ago < HOUR_MS)
        return rtf.format(-Math.floor(ago / MINUTE_MS), 'minute');
    if (ago < DAY_MS)
        return rtf.format(-Math.floor(ago / HOUR_MS), 'hour');
    return rtf.format(-Math.floor(ago / DAY_MS), 'day');
};
// «Chrome 131 · macOS»; нерозпізнане — null, текст підставляє компонент.
export const sessionDevice = (session) => {
    const parts = [session.browser, session.os].filter((part) => !!part);
    return parts.length ? parts.join(' · ') : null;
};
// Поточна сесія першою, далі — від найсвіжішої активності.
export const sortSessions = (sessions) => ([...sessions].sort((a, b) => (Number(b.is_current) - Number(a.is_current) || b.last_active_ts - a.last_active_ts)));
